arguments.command:
node -e "
const d = require('./frontend/src/services/demo.js');
const source = d.DEMO_CODE;
const lines = source.split('\n');
console.log('Source line count:', lines.length);
const affectedLine = 29;
const affectedIdx = affectedLine - 1;
console.log('affected_idx:', affectedIdx);
console.log('out of bounds?', affectedIdx >= lines.length);
console.log('Line 29 content:', JSON.stringify(lines[affectedIdx]));
console.log('Has items[0]?', /\w+\[\w+\]/.test(lines[affectedIdx]));
"

